import{_ as t,o as n,c as a,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"ADR-002 — MongoDB + PostgreSQL Split","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-002-database-split.md","filePath":"adr/ADR-002-database-split.md"}'),i={name:"adr/ADR-002-database-split.md"};function s(r,e,c,l,h,g){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-002-—-mongodb-postgresql-split" tabindex="-1">ADR-002 — MongoDB + PostgreSQL Split <a class="header-anchor" href="#adr-002-—-mongodb-postgresql-split" aria-label="Permalink to &quot;ADR-002 — MongoDB + PostgreSQL Split&quot;">​</a></h1><p><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>business-service cần lưu 2 loại dữ liệu bản chất khác nhau: dữ liệu nghiệp vụ có cấu trúc, quan hệ chặt, giao dịch tiền thật (identity, Agency/Workspace, billing) và dữ liệu nội dung có schema linh hoạt, thay đổi nhanh theo tính năng (Task, Post, Material, Livestream). Cần quyết định dùng 1 DB duy nhất hay tách 2 loại.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Tách 2 database engine trong cùng business-service:</strong></p><ul><li><strong>PostgreSQL</strong> — 23 bảng: Identity (users, oauth, roles), Organization (agencies, workspaces, members), Commerce (media packages, campaigns), Collaborator, Billing (subscriptions, transactions, AI credit).</li><li><strong>MongoDB</strong> — 14 collection: Task, TaskApproval, Post, ContentRequest, Material, Brand/Hashtag Collection, Livestream, Survey, Mail Template, Social Account, Notification.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Tích cực:</strong></p><ul><li>PostgreSQL đảm bảo <strong>ACID</strong> cho giao dịch tiền thật (FR 3.9.3 Make Payment yêu cầu rõ ACID) và ràng buộc toàn vẹn quan hệ (1 Owner/Agency, 1 Manager/Workspace, FK giữa agency↔workspace↔member).</li><li>MongoDB cho phép schema linh hoạt khi thêm field mới cho Task/Post (3 loại nội dung: Post/Livestream/Survey dùng chung khung Approval Sequence nhưng field riêng biệt) mà không cần migration ALTER TABLE.</li><li>Content/Task volume ghi cao (mỗi comment, mỗi version content) phù hợp write throughput của MongoDB hơn PostgreSQL.</li></ul><p><strong>Tiêu cực:</strong></p><ul><li>Không có JOIN cross-DB ở tầng engine — mọi tham chiếu (vd: <code>tasks.workspaceId</code>) là soft reference bằng ID string, business-service phải tự join ở application layer (xem <code>docs/architecture/db-ownership-diagram.html</code> — Cross-DB Reference Strategy).</li><li>2 connection pool, 2 hệ thống backup/migration riêng — tăng vận hành so với 1 DB duy nhất.</li><li>Risk: dữ liệu không nhất quán nếu 1 thao tác cần ghi cả 2 DB (vd: approve Campaign → tạo Task) mà không có transaction xuyên DB — cần xử lý bằng application-level compensating logic, không có 2-phase commit thật.</li></ul>',12)])])}const u=t(i,[["render",s]]);export{p as __pageData,u as default};
